<script>
  function pysOpenUrgentPopup() {
    var popup = document.getElementById('pys-urgent-popup');
    if (popup) {
      popup.classList.add('pys-show-popup');
    }
  }

  function pysCloseUrgentPopup() {
    var popup = document.getElementById('pys-urgent-popup');
    if (popup) {
      popup.classList.remove('pys-show-popup');
    }
  }

  setTimeout(function () {
    pysOpenUrgentPopup();
  }, 4000);

  document.addEventListener('keydown', function(event) {
    if (event.key === 'Escape') {
      pysCloseUrgentPopup();
    }
  });

  document.addEventListener('click', function(event) {
    var popup = document.getElementById('pys-urgent-popup');
    if (event.target === popup) {
      pysCloseUrgentPopup();
    }
  });
